export class EventEmitter {
    constructor() {
        this._events = Object.create(null);
        this._maxListeners = 10;
    }

    addListener(type, listener) {
        if (typeof listener !== 'function') throw new TypeError('listener must be a function');
        const key = String(type);
        const list = this._events[key] || (this._events[key] = []);
        list.push(listener);
        if (list.length > this._maxListeners && this._maxListeners > 0 && !list._mochiWarned) {
            list._mochiWarned = true;
            console.warn(`mochievents: possible memory leak: ${list.length} listeners for '${key}'`);
        }
        return this;
    }

    on(type, listener) {
        return this.addListener(type, listener);
    }

    prependListener(type, listener) {
        if (typeof listener !== 'function') throw new TypeError('listener must be a function');
        const key = String(type);
        const list = this._events[key] || (this._events[key] = []);
        list.unshift(listener);
        return this;
    }

    once(type, listener) {
        if (typeof listener !== 'function') throw new TypeError('listener must be a function');
        const self = this;
        const wrapped = function (...args) {
            self.removeListener(type, wrapped);
            return listener.apply(this, args);
        };
        wrapped._mochiOnce = true;
        wrapped._mochiOriginal = listener;
        return this.addListener(type, wrapped);
    }

    prependOnceListener(type, listener) {
        if (typeof listener !== 'function') throw new TypeError('listener must be a function');
        const self = this;
        const wrapped = function (...args) {
            self.removeListener(type, wrapped);
            return listener.apply(this, args);
        };
        wrapped._mochiOnce = true;
        wrapped._mochiOriginal = listener;
        return this.prependListener(type, wrapped);
    }

    removeListener(type, listener) {
        const key = String(type);
        const list = this._events[key];
        if (!list) return this;
        for (let i = 0; i < list.length; i++) {
            const item = list[i];
            if (item === listener || (item._mochiOnce && item._mochiOriginal === listener)) {
                list.splice(i, 1);
                break;
            }
        }
        if (list.length === 0) delete this._events[key];
        return this;
    }

    off(type, listener) {
        return this.removeListener(type, listener);
    }

    removeAllListeners(type) {
        if (type === undefined) this._events = Object.create(null);
        else delete this._events[String(type)];
        return this;
    }

    listeners(type) {
        const list = this._events[String(type)];
        if (!list) return [];
        return list.map((listener) => listener._mochiOriginal || listener);
    }

    rawListeners(type) {
        const list = this._events[String(type)];
        return list ? list.slice() : [];
    }

    listenerCount(type) {
        const list = this._events[String(type)];
        return list ? list.length : 0;
    }

    setMaxListeners(n) {
        this._maxListeners = Number(n) || 0;
        return this;
    }

    getMaxListeners() {
        return this._maxListeners;
    }

    emit(type, ...args) {
        const key = String(type);
        const list = this._events[key];
        if (!list || list.length === 0) {
            if (key === 'error') {
                const err = args[0] || new Error('Unhandled error');
                throw err instanceof Error ? err : new Error(String(err));
            }
            return false;
        }
        const copy = list.slice();
        for (const listener of copy) listener.apply(this, args);
        return true;
    }

    eventNames() {
        return Object.keys(this._events);
    }
}

EventEmitter.defaultMaxListeners = 10;

export default EventEmitter;

EventEmitter.EventEmitter = EventEmitter;

/**
 * once(emitter, name) -> Promise that resolves with the event args when `name`
 * fires, or rejects if an 'error' event fires first. Mirrors node:events.once
 * for the common case (no AbortSignal support here). The listeners are removed
 * as soon as the promise settles, so repeated calls do not leak.
 */
export function once(emitter, name) {
    return new Promise((resolve, reject) => {
        const onEvent = (...args) => { cleanup(); resolve(args); };
        const onError = (err) => { cleanup(); reject(err); };
        function cleanup() {
            if (typeof emitter.off === 'function') {
                emitter.off(name, onEvent);
                emitter.off('error', onError);
            } else if (typeof emitter.removeListener === 'function') {
                emitter.removeListener(name, onEvent);
                emitter.removeListener('error', onError);
            }
        }
        if (name !== 'error' && typeof emitter.once === 'function') {
            emitter.once(name, onEvent);
            emitter.once('error', onError);
        } else if (name !== 'error') {
            emitter.on(name, onEvent);
            emitter.on('error', onError);
        } else {
            emitter.once(name, onEvent);
        }
    });
}
